python - <<'PY'
import glob,json,os
for f in glob.glob('factors/*.json'):
 if f.endswith('factor_ensemble.json'): continue
 print('\n',f)
 try:
  d=json.load(open(f)); print({k:d.get(k) for k in ['factor_id','name','category','ic','icir','IC','ICIR','turnover','coverage']})
 except Exception as e: print(e)
PY
tail -n 45 memory.txt

